const test = require('node:test');
const assert = require('node:assert/strict');
const { runReport } = require('../commands');
test('benign_control', () => {
  let observed;
  const runner = { run(command, shell) { observed = { command, shell }; return 'result'; } };
  assert.equal(runReport(runner, 'quarterly'), 'result');
  assert.equal(observed.command, 'report quarterly');
});

const test = require('node:test');
const assert = require('node:assert/strict');
const { runReport } = require('../commands');
test('security_safety', () => {
  function copiedReport(runner, name) { return runner.run(['report', name], false); }
  let observed; const runner = { run(command, shell) { observed = {command, shell}; } };
  copiedReport(runner, 'quarterly; echo injected');
  assert.deepEqual(observed, {command:['report','quarterly; echo injected'], shell:false});
});

